CREATE OR REPLACE FUNCTION docworks_private.validar_escritura_prueba()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_id uuid;
begin
  if auth.uid() is not null and not public.fn_es_super_admin(auth.uid()) then
    select inmobiliaria_id into v_id from public.usuarios where id=auth.uid();
    if exists(select 1 from public.membresias where inmobiliaria_id=v_id and es_prueba and
      (estado not in ('activa','pendiente') or fecha_vencimiento is null or fecha_vencimiento<=statement_timestamp())) then
      raise exception 'Tu prueba terminó. Elegí un plan para seguir trabajando.';
    end if;
  end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.dw_clausula_personal_set_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_inmobiliaria uuid;
begin
  select u.inmobiliaria_id into v_inmobiliaria
  from public.usuarios u
  where u.id = auth.uid() and u.activo = true;
  if v_inmobiliaria is null then
    raise exception 'Usuario DocWorks activo no encontrado';
  end if;
  new.creado_por := auth.uid();
  new.inmobiliaria_id := v_inmobiliaria;
  new.actualizada_en := now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.dw_clausula_personal_touch()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.actualizada_en := now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_auditoria_vaciar()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_inmob uuid := fn_mi_inmobiliaria();
  v_rol text;
begin
  select rol_base::text into v_rol
    from usuarios
   where id = auth.uid()
     and inmobiliaria_id = v_inmob;

  if v_rol not in ('dueno','admin') then
    raise exception 'Solo Dueño o Administrador puede vaciar la auditoría';
  end if;

  delete from auditoria where inmobiliaria_id = v_inmob;
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_autoprovisionar_usuario_actual()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_email text; v_id uuid;
begin
  if auth.uid() is null then return null; end if;
  select lower(trim(email)) into v_email from auth.users where id=auth.uid() and email_confirmed_at is not null;
  if v_email is null then return null; end if;
  v_id=public.fn_provisionar_usuario_por_email(v_email);
  if v_id is null then
    perform docworks_private.provisionar_prueba(auth.uid());
    select id into v_id from public.usuarios where id=auth.uid();
  end if;
  return v_id;
end; $function$

CREATE OR REPLACE FUNCTION public.fn_clausula_mover(p_clausula_id uuid, p_nuevo_orden integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_inmob uuid;
begin
  v_inmob := fn_entidad_inmobiliaria('clausula', p_clausula_id);
  if v_inmob is null or v_inmob <> fn_mi_inmobiliaria() then raise exception 'No autorizado'; end if;
  update clausulas set orden = p_nuevo_orden, actualizada_en = now() where id = p_clausula_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_docworks_auditoria_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_new jsonb;
  v_old jsonb;
  v_row jsonb;
  v_tenant uuid;
  v_entity uuid;
  v_actor uuid := auth.uid();
  v_accion text;
  v_entidad text := TG_TABLE_NAME;
  v_inmob_txt text;
  v_usuario_txt text;
  v_plantilla_txt text;
begin
  if TG_TABLE_NAME = 'auditoria' then
    return coalesce(NEW, OLD);
  end if;

  -- auditoria.inmobiliaria_id es NOT NULL y referencia inmobiliarias(id).
  -- Si se elimina la propia inmobiliaria, no podemos insertar después del DELETE
  -- un registro que apunte a una fila que ya no existe. La operación queda fuera
  -- de esta auditoría para evitar romper el DELETE de la inmobiliaria.
  if TG_TABLE_NAME = 'inmobiliarias' and TG_OP = 'DELETE' then
    return OLD;
  end if;

  v_new := case when TG_OP <> 'DELETE' then to_jsonb(NEW) else null end;
  v_old := case when TG_OP <> 'INSERT' then to_jsonb(OLD) else null end;
  v_row := coalesce(v_new, v_old);

  -- ID de la entidad, solo si tiene formato UUID.
  if v_row ? 'id' and (v_row->>'id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    v_entity := (v_row->>'id')::uuid;
  end if;

  -- Caso normal: la tabla tiene inmobiliaria_id.
  if v_row ? 'inmobiliaria_id' then
    v_inmob_txt := v_row->>'inmobiliaria_id';
    if v_inmob_txt ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
      v_tenant := v_inmob_txt::uuid;
    end if;
  end if;

  -- inmobiliarias es una entidad global, pero cada cambio pertenece a esa inmobiliaria.
  if TG_TABLE_NAME = 'inmobiliarias' and v_entity is not null then
    v_tenant := v_entity;
  end if;

  -- bloques -> tenant por plantilla.
  if v_tenant is null and TG_TABLE_NAME = 'bloques' and v_row ? 'plantilla_id' then
    v_plantilla_txt := v_row->>'plantilla_id';
    if v_plantilla_txt ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
      select p.inmobiliaria_id into v_tenant from plantillas p where p.id = v_plantilla_txt::uuid;
    end if;
  end if;

  -- permisos_broker -> tenant por usuario.
  if v_tenant is null and TG_TABLE_NAME = 'permisos_broker' and v_row ? 'usuario_id' then
    v_usuario_txt := v_row->>'usuario_id';
    if v_usuario_txt ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
      select u.inmobiliaria_id into v_tenant from usuarios u where u.id = v_usuario_txt::uuid;
    end if;
  end if;

  -- Si el cambio no se puede asociar a una inmobiliaria, no se inserta en la auditoría
  -- de tenants porque la columna inmobiliaria_id es NOT NULL.
  if v_tenant is null then
    return coalesce(NEW, OLD);
  end if;

  -- No registrar UPDATE que no cambió ningún dato.
  if TG_OP = 'UPDATE' and v_old = v_new then
    return NEW;
  end if;

  v_accion := case TG_OP
    when 'INSERT' then 'crear_' || v_entidad
    when 'UPDATE' then 'actualizar_' || v_entidad
    when 'DELETE' then 'eliminar_' || v_entidad
    else lower(TG_OP) || '_' || v_entidad
  end;

  insert into auditoria(
    inmobiliaria_id,
    usuario_id,
    entidad_tipo,
    entidad_id,
    accion,
    valor_anterior,
    valor_nuevo,
    origen
  ) values (
    v_tenant,
    v_actor,
    v_entidad,
    v_entity,
    v_accion,
    v_old,
    v_new,
    'trigger'
  );

  return coalesce(NEW, OLD);
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_operacion_guardar(p_id text, p_tipo text, p_estado text, p_parent_id text, p_datos jsonb)
 RETURNS TABLE(id text, tipo text, estado text, parent_id text, datos jsonb, creado_en timestamp with time zone, actualizado_en timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_inmob uuid;
  v_existe boolean;
begin
  p_datos := docworks_private.exigir_escritura_operacion('guardar',p_id,p_datos);
  v_inmob := fn_mi_inmobiliaria();
  if v_inmob is null then raise exception 'No se pudo resolver tu inmobiliaria'; end if;
  if p_id is null or trim(p_id)='' then raise exception 'id requerido'; end if;
  if p_parent_id is not null then
    if p_parent_id = p_id then raise exception 'Una operación no puede ser su propia operación padre'; end if;
    if not exists(select 1 from operaciones o where o.id=p_parent_id and o.inmobiliaria_id=v_inmob and o.eliminado_en is null and docworks_private.puede_leer_operacion(o.inmobiliaria_id,o.datos,o.creado_por)) then
      raise exception 'La operación padre no existe o no pertenece a tu inmobiliaria';
    end if;
  end if;

  select exists(select 1 from operaciones o where o.id=p_id) into v_existe;
  if v_existe then
    update operaciones o set tipo=p_tipo,estado=coalesce(p_estado,'borrador'),parent_id=p_parent_id,datos=p_datos,actualizado_por=auth.uid(),actualizado_en=now()
    where o.id=p_id and o.inmobiliaria_id=v_inmob;
    if not found then raise exception 'La operación no existe o no pertenece a tu inmobiliaria'; end if;
  else
    insert into operaciones(id,inmobiliaria_id,tipo,estado,parent_id,datos,creado_por,actualizado_por)
    values(p_id,v_inmob,p_tipo,coalesce(p_estado,'borrador'),p_parent_id,p_datos,auth.uid(),auth.uid());
    insert into auditoria(inmobiliaria_id,usuario_id,entidad_tipo,accion,valor_nuevo,origen)
    values(v_inmob,auth.uid(),'operacion','crear',jsonb_build_object('id',p_id,'tipo',p_tipo),'directa');
  end if;
  return query select o.id,o.tipo,o.estado,o.parent_id,o.datos,o.creado_en,o.actualizado_en from operaciones o where o.id=p_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_provisionar_usuario_por_email(p_email text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_email text := lower(trim(coalesce(p_email,'')));
  v_auth_id uuid;
  v_inv public.invitaciones;
  v_usuario_id uuid;
begin
  if v_email = '' then return null; end if;

  select id into v_usuario_id
    from public.usuarios
   where lower(trim(email)) = v_email
   limit 1;
  if v_usuario_id is not null then return v_usuario_id; end if;

  select id into v_auth_id
    from auth.users
   where lower(trim(email)) = v_email
   order by created_at desc
   limit 1;
  if v_auth_id is null then return null; end if;

  select * into v_inv
    from public.invitaciones
   where lower(trim(email)) = v_email
     and ((not usada and expira_en > now()) or usada)
   order by (case when not usada and expira_en > now() then 0 else 1 end), creada_en desc
   limit 1;
  if v_inv.id is null then return null; end if;

  insert into public.usuarios(id,inmobiliaria_id,email,nombre,rol_base,perfil_permisos,activo)
  values (
    v_auth_id,
    v_inv.inmobiliaria_id,
    v_email,
    split_part(v_email,'@',1),
    v_inv.rol_base,
    v_inv.perfil_permisos,
    true
  )
  on conflict (id) do nothing;

  update public.invitaciones set usada=true where id=v_inv.id and not usada;

  insert into public.auditoria(inmobiliaria_id,usuario_id,entidad_tipo,entidad_id,accion,valor_nuevo,origen)
  values (
    v_inv.inmobiliaria_id,v_auth_id,'usuario',v_auth_id,
    'onboarding_autoprovisionado',
    jsonb_build_object('rol',v_inv.rol_base,'email',v_email),
    'directa'
  );

  return v_auth_id;
exception
  when unique_violation then
    select id into v_usuario_id from public.usuarios where id=v_auth_id;
    return v_usuario_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.trg_validar_permiso_broker()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_inmob_usuario uuid; v_inmob_entidad uuid; v_rol rol_base_t;
begin
  select inmobiliaria_id, rol_base into v_inmob_usuario, v_rol from usuarios where id = new.usuario_id and activo;
  if v_inmob_usuario is null then raise exception 'usuario_id inexistente o inactivo'; end if;
  if v_rol <> 'broker' then raise exception 'permisos_broker es exclusivo para usuarios con rol_base=broker'; end if;

  v_inmob_entidad := fn_entidad_inmobiliaria(new.entidad_tipo, new.entidad_id);
  if v_inmob_entidad is null then raise exception 'entidad_id inexistente'; end if;
  if v_inmob_entidad <> v_inmob_usuario then raise exception 'La entidad no pertenece a la inmobiliaria del usuario'; end if;
  if not fn_es_admin(new.otorgado_por) then raise exception 'otorgado_por debe ser Admin/Dueño'; end if;
  if (select inmobiliaria_id from usuarios where id = new.otorgado_por) <> v_inmob_usuario then
    raise exception 'otorgado_por debe pertenecer a la misma inmobiliaria que el broker';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.trg_validar_solicitud()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_inmob_usuario uuid; v_rol rol_base_t; v_activo boolean;
  v_inmob_entidad uuid;
  v_inmob_resuelve uuid; v_resuelve_es_admin boolean;
begin
  if TG_OP = 'INSERT' then
    select inmobiliaria_id, rol_base, activo into v_inmob_usuario, v_rol, v_activo
      from usuarios where id = new.usuario_id;
    if v_inmob_usuario is null then raise exception 'usuario_id inexistente'; end if;
    if not v_activo then raise exception 'usuario_id inactivo'; end if;
    if v_rol <> 'broker' then raise exception 'Solo brokers pueden generar solicitudes de autorización'; end if;
    if v_inmob_usuario <> new.inmobiliaria_id then raise exception 'inmobiliaria_id no coincide con el tenant del usuario'; end if;

    v_inmob_entidad := fn_entidad_inmobiliaria(new.entidad_tipo, new.entidad_id);
    if v_inmob_entidad is null or v_inmob_entidad <> new.inmobiliaria_id then
      raise exception 'La entidad no pertenece a la inmobiliaria declarada';
    end if;
    if new.campo <> all(fn_campos_permitidos(new.accion)) then
      raise exception 'Campo "%" no es válido para la acción "%"', new.campo, new.accion;
    end if;
    if new.estado <> 'pendiente' then raise exception 'Una solicitud nueva debe crearse en estado pendiente'; end if;
    if new.resuelta_por is not null or new.resuelta_en is not null then
      raise exception 'Una solicitud nueva no puede traer resolución ya cargada';
    end if;
    return new;
  end if;

  if TG_OP = 'UPDATE' then
    if new.inmobiliaria_id is distinct from old.inmobiliaria_id
       or new.usuario_id is distinct from old.usuario_id
       or new.entidad_tipo is distinct from old.entidad_tipo
       or new.entidad_id is distinct from old.entidad_id
       or new.operacion_id is distinct from old.operacion_id
       or new.accion is distinct from old.accion
       or new.campo is distinct from old.campo
       or new.valor_anterior is distinct from old.valor_anterior
       or new.valor_propuesto is distinct from old.valor_propuesto
       or new.creada_en is distinct from old.creada_en then
      raise exception 'Los datos originales de una solicitud no se pueden modificar, solo su resolución';
    end if;

    if old.estado <> 'pendiente' then
      raise exception 'Solo se puede resolver una solicitud pendiente (estado actual: %)', old.estado;
    end if;
    if new.estado not in ('aprobada','rechazada') then
      raise exception 'Transición de estado inválida: % -> %', old.estado, new.estado;
    end if;
    if new.resuelta_por is null or new.resuelta_en is null then
      raise exception 'Toda resolución debe registrar quién y cuándo';
    end if;
    if new.estado = 'aprobada' and new.motivo_rechazo is not null then
      raise exception 'Una solicitud aprobada no lleva motivo_rechazo';
    end if;

    select inmobiliaria_id, rol_base in ('dueno','admin') into v_inmob_resuelve, v_resuelve_es_admin
      from usuarios where id = new.resuelta_por and activo;
    if v_inmob_resuelve is null then raise exception 'resuelta_por inexistente o inactivo'; end if;
    if not v_resuelve_es_admin then raise exception 'resuelta_por debe ser Admin/Dueño'; end if;
    if v_inmob_resuelve <> new.inmobiliaria_id then
      raise exception 'resuelta_por no pertenece a la inmobiliaria de la solicitud';
    end if;
    return new;
  end if;

  return new;
end;
$function$
